lib='''
def find_rects(grid, color, h=2, w=2):
    """All h x w blocks of the given color, as (top, left) of their top-left cell."""
    return [(i, j) for i in range(len(grid) - h + 1) for j in range(len(grid[0]) - w + 1)
            if all(grid[a][b] == color for a in range(i, i + h) for b in range(j, j + w))]

def paint_rect(grid, top, left, color, h=2, w=2):
    """Fill the h x w block whose top-left cell is (top, left) with the color."""
    out = [row[:] for row in grid]
    for a in range(top, top + h):
        for b in range(left, left + w):
            out[a][b] = color
    return out

def touches_border(grid, top, left, h=2, w=2):
    """Whether the h x w block at (top, left) touches the grid's outer edge."""
    return top == 0 or left == 0 or top + h == len(grid) or left + w == len(grid[0])
'''
